function toggleSaved(protocol){const p=String(protocol||'').toUpperCase();let list=bookmarks();list=list.includes(p)?list.filter(x=>x!==p):[p,...list.filter(Boolean)].slice(0,50);try{localStorage.setItem(BOOKMARK_KEY,JSON.stringify(list))}catch{toast('Não foi possível guardar o protocolo neste aparelho.')}return list.includes(p)}
