function neighborhoodStats(name){const rows=neighborhoodRecords(name),open=rows.filter(o=>o.status!=='Resolvida').length,resolved=rows.filter(o=>o.status==='Resolvida').length,mapped=rows.filter(o=>Number.isFinite(o.lat)&&Number.isFinite(o.lng)).length,cats=CATEGORIES.map(c=>({id:c[0],label:c[2],count:rows.filter(o=>o.category===c[0]).length})).filter(x=>x.count).sort((a,b)=>b.count-a.count),agencies=[...new Map(rows.map(o=>{const r=routingReference(o.category);return[r.agencyId,r.agencyLabel]}))].map(([id,label])=>({id,label,count:rows.filter(o=>routingReference(o.category).agencyId===id).length})).sort((a,b)=>b.count-a.count);return{rows,total:rows.length,open,resolved,mapped,cats,agencies,topCat:cats[0]||null}}
function distanceKm(aLat,aLng,bLat,bLng){const r=6371,toRad=x=>x*Math.PI/180,dLat=toRad(bLat-aLat),dLng=toRad(bLng-aLng),v=Math.sin(dLat/2)**2+Math.cos(toRad(aLat))*Math.cos(toRad(bLat))*Math.sin(dLng/2)**2;return 2*r*Math.asin(Math.sqrt(v))}
function normText(v=''){return String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function dataUrlBytes(data=''){const comma=data.indexOf(',');const base=comma>=0?data.slice(comma+1):data;return Math.ceil(base.length*3/4)}
function fileDataUrl(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result||''));r.onerror=()=>reject(new Error('read'));r.readAsDataURL(file)})}
function imageFromUrl(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('image'));img.src=src})}
async function preparePhoto(file){
 if(!file)return'';
 if(!/^image\/(jpeg|png|webp)$/i.test(file.type||''))throw new Error('type');
 if(file.size>8*1024*1024)throw new Error('size');
 const raw=await fileDataUrl(file);
 if(file.size<=1200*1024)return raw;
 const img=await imageFromUrl(raw),maxSide=1600,scale=Math.min(1,maxSide/Math.max(img.naturalWidth||img.width,img.naturalHeight||img.height));
 const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round((img.naturalWidth||img.width)*scale));canvas.height=Math.max(1,Math.round((img.naturalHeight||img.height)*scale));
 const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);
 let data='';for(const q of [.84,.74,.64,.54]){data=canvas.toDataURL('image/jpeg',q);if(dataUrlBytes(data)<=1350*1024)break}
 if(dataUrlBytes(data)>1450*1024)throw new Error('size');
 return data
}
