function lastUpdateDate(o){const values=(o?.history||[]).map(h=>new Date(h[1]).getTime()).filter(Number.isFinite),own=new Date(o?.updated||o?.created||0).getTime();if(Number.isFinite(own))values.push(own);return values.length?new Date(Math.max(...values)):null}
function relativeTime(d){if(!d)return'';const ms=Date.now()-new Date(d).getTime(),day=86400000;if(!Number.isFinite(ms)||ms<0)return'';if(ms<3600000)return'Atualizado há menos de 1 h';if(ms<day)return'Atualizado há '+Math.max(1,Math.floor(ms/3600000))+' h';const n=Math.floor(ms/day);return n===1?'Atualizado há 1 dia':'Atualizado há '+n+' dias'}
function nearbySimilar(lat,lng,category,exclude='',limit=3){if(!Number.isFinite(lat)||!Number.isFinite(lng)||!category)return[];return publicMetricRecords().filter(o=>o.protocol!==exclude&&o.category===category&&o.status!=='Resolvida'&&Number.isFinite(o.lat)&&Number.isFinite(o.lng)).map(o=>Object.assign({},o,{_distance:distanceKm(lat,lng,o.lat,o.lng)})).filter(o=>o._distance<=1.2).sort((a,b)=>a._distance-b._distance).slice(0,limit)}
function neighborhoodSimilar(bairro,category,exclude='',limit=3){const b=normText(bairro);if(!b||!category)return[];return publicMetricRecords().filter(o=>o.protocol!==exclude&&o.category===category&&o.status!=='Resolvida'&&normText(o.bairro)===b).slice(0,limit)}

function fmt(d){try{return new Date(d).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}catch{return esc(d)}}
