function publicMetricRecords(){return db.occurrences.filter(o=>o.public!==false&&(!o.cloudOrigin||o.moderationStatus==='approved'))}
async function syncPublicCloudOccurrences(){
 const api=cloudApi();if(!api?.listPublicOccurrences)return 0;
 try{
  if(api.health&&!api.state?.connected)await api.health();if(!api.state?.connected)return 0;
  const rows=await api.listPublicOccurrences(250);if(!Array.isArray(rows))return 0;let changed=0;
  for(const row of rows){const protocol=String(row.protocol||'').toUpperCase();if(!protocol)continue;const idx=db.occurrences.findIndex(o=>String(o.protocol).toUpperCase()===protocol),previous=idx>=0?db.occurrences[idx]:null,mapped=remoteToOccurrence(row,previous);if(previous?.localOwner){mapped.localOwner=true;mapped.privateData=previous.privateData||{}}if(idx>=0)db.occurrences[idx]=mapped;else db.occurrences.push(mapped);changed++}
  if(changed){db.occurrences.sort((a,b)=>new Date(b.created)-new Date(a.created));window.CidadeConectaLocalDB=db;saveDB()}return changed;
 }catch(error){console.warn('Sincronização pública indisponível:',String(error?.message||error));return 0}
}
