 const timedOut=/tempo limite|timeout/i.test(String(state.lastError||''));
 if(state.status==='checking')return pageHead('Acesso interno','Validando sessão','Área protegida para a equipe do Cidade Conecta.')+'<section class="section"><div class="wrap"><div id="adminAuthChecking" class="card adminAuthCardV57" role="status" aria-live="polite" aria-busy="true"><span class="miniLabel">Acesso protegido</span><h2>Confirmando seu acesso…</h2><div class="skeletonStackV56" aria-hidden="true"><span></span><span></span><span></span></div></div></div></section>';
 if(state.status==='anonymous')return pageHead('Acesso interno','Painel da equipe','Entre com sua conta interna para acessar a fila de triagem.')+'<section class="section"><div class="wrap"><form id="adminLoginForm" class="card adminAuthCardV57 adminLoginCompactV57" autocomplete="on"><span class="miniLabel">Acesso restrito</span><h2>Entrar</h2><p class="muted">Use o e-mail cadastrado para a equipe.</p><div class="field"><label for="adminEmail">E-mail</label><input id="adminEmail" name="email" type="email" autocomplete="username" required maxlength="160"></div><div class="field"><label for="adminPassword">Senha</label><div class="passwordFieldV57"><input id="adminPassword" name="password" type="password" autocomplete="current-password" required minlength="8" maxlength="200"><button id="adminTogglePassword" type="button" class="passwordToggleV57" aria-label="Mostrar senha">Mostrar</button></div></div><div id="adminLoginError" class="notice warning hidden" role="alert"></div><button id="adminLoginBtn" class="btn primary" type="submit">Entrar</button><p class="small muted">O cadastro de equipe não é feito por esta tela.</p></form></div></section>';
